'use strict';
(() => {
 const canvas=document.getElementById('field'),button=document.getElementById('motion-toggle');
 const ctx=canvas.getContext('2d'),reduced=matchMedia('(prefers-reduced-motion: reduce)');
 let running=!reduced.matches,raf=0,angle=0,width=0,height=0,last=0;
 const points=[];let seed=54;const random=()=>{seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;};
 for(let i=0;i<2200;i++){const t=random()*Math.PI*2,r=Math.sqrt(random())*480;points.push({x:Math.cos(t)*r,y:Math.sin(t)*r*.75,z:(random()-.5)*420,size:random()>.96?2+random()*2:.25+random(),warm:random()>.85,phase:random()*6.28});}
 function resize(){const rect=canvas.getBoundingClientRect(),scale=Math.min(devicePixelRatio||1,1.5);width=rect.width;height=rect.height;canvas.width=width*scale;canvas.height=height*scale;ctx?.setTransform(scale,0,0,scale,0,0);draw();}
 function draw(){if(!ctx)return;ctx.clearRect(0,0,width,height);const scale=Math.min(width/850,height/700),cx=width/2,cy=height*.45;const rotate=angle*.2;
  for(const p of points){const x=p.x*Math.cos(rotate)+p.z*Math.sin(rotate),z=-p.x*Math.sin(rotate)+p.z*Math.cos(rotate),y=p.y*.8+z*.25,k=430/(430+z);const px=cx+x*k*scale,py=cy+y*k*scale;const radius=p.size*k*scale*(1+.2*Math.sin(angle+p.phase));ctx.beginPath();ctx.fillStyle=p.warm?'rgba(218,174,121,.72)':'rgba(218,236,255,.88)';ctx.shadowColor=p.warm?'#d5aa77':'#9ecac1';ctx.shadowBlur=radius>1.5?7:0;ctx.arc(px,py,Math.max(.3,radius),0,Math.PI*2);ctx.fill();}ctx.shadowBlur=0;}
 function tick(time){if(!running||document.hidden){raf=0;return;}if(time-last>30){angle+=.006;draw();last=time;}raf=requestAnimationFrame(tick);}
 function sync(){button.textContent=running?'Ⅱ':'▶';button.setAttribute('aria-label',running?'Pause abstract animation':'Play abstract animation');if(running&&!raf&&!document.hidden)raf=requestAnimationFrame(tick);else if(!running){cancelAnimationFrame(raf);raf=0;}}
 button.addEventListener('click',()=>{running=!running;sync();});reduced.addEventListener('change',event=>{if(event.matches){running=false;sync();}});document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0;}else sync();});window.addEventListener('resize',resize);resize();sync();
})();
(() => {
 const byId=id=>document.getElementById(id);let data,traceIndex=0,field='input';
 const element=(tag,text,className)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(className)e.className=className;return e;};
 function tab(selected,focus=false){field=selected;document.querySelectorAll('[data-field]').forEach(b=>{const active=b.dataset.field===selected;b.setAttribute('aria-selected',String(active));b.tabIndex=active?0:-1;if(active&&focus)b.focus();});byId('trace-panel').setAttribute('aria-labelledby','tab-'+selected);renderTrace();}
 function renderTrace(){if(!data)return;const t=data.traces[traceIndex],steps=t.steps;let value=t[field];const controls=byId('step-controls');controls.hidden=field!=='steps';if(field==='steps'){const slider=byId('step-slider');slider.max=steps.length-1;slider.value=Math.min(Number(slider.value),steps.length-1);const i=Number(slider.value);value=steps[i];byId('step-count').textContent=`${i+1} / ${steps.length}`;byId('step-prev').disabled=i===0;byId('step-next').disabled=i===steps.length-1;}
  byId('trace-json').textContent=JSON.stringify(value,null,2);byId('trace-verdict').textContent=t.verification.success?'Task PASS · replay verified':'Task FAIL · replay verified';byId('trace-verdict').className='label '+(t.verification.success?'positive':'negative');byId('trace-output').textContent=t.output.answer??(t.domain==='coding'?'Repair executed':'Motion action executed');byId('trace-scoring').textContent=t.verification.evaluator;byId('trace-source').href=t.source;byId('trace-caption').textContent=`${t.label} · ${t.version}. Original claims are preserved. Direct/kernel agreement: ${t.parity?'yes':'no'}.`;}
 function table(target,headers,rows){const wrap=element('div',undefined,'table-wrap'),table=element('table'),head=element('thead'),tr=element('tr');headers.forEach(h=>{const th=element('th',h);th.scope='col';tr.append(th);});head.append(tr);table.append(head);const body=element('tbody');rows.forEach(row=>{const tr=element('tr');row.forEach(cell=>tr.append(element('td',String(cell))));body.append(tr);});table.append(body);wrap.append(table);target.replaceChildren(wrap);}
 function bars(target,rows,max,percent=false){target.replaceChildren();for(const row of rows){const line=element('div',undefined,'bar-row'),track=element('div',undefined,'bar-track'),fill=element('div',undefined,'bar-fill');fill.style.width=`${Math.max(0,Math.min(100,100*row.value/max))}%`;track.append(fill);if(row.interval){const ci=element('span',undefined,'bar-interval');ci.style.left=100*row.interval[0]/max+'%';ci.style.width=100*(row.interval[1]-row.interval[0])/max+'%';ci.setAttribute('aria-hidden','true');track.append(ci);}line.append(element('span',row.label,'bar-label'),track,element('span',percent?(row.value*100).toFixed(2)+'%':row.value.toFixed(5),'bar-value'));target.append(line);}}
 function wilson(k,n){const z=1.959963984540054,p=k/n,d=1+z*z/n,c=(p+z*z/(2*n))/d,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return [Math.max(0,c-h),Math.min(1,c+h)];}
 function math(){if(!data)return;const seed=byId('math-seed').value,family=byId('math-family').value;const methods=[['recurrent','Recurrent'],['reset_hidden','Reset hidden'],['memory_only','Local memory'],['zero_weight','Zero weights'],['zero_weight_memory','Zero + memory']];const rows=methods.map(([key,label])=>{const c=data.math[key][seed][family];return{label,value:c.exact_accuracy,interval:c.exact_wilson95||wilson(c.correct,c.tasks),count:c.correct,n:c.tasks};});bars(byId('math-chart'),rows,1,true);byId('math-note').textContent=`Seed ${seed} · ${rows[0].n} independent tasks per condition. Frozen saved predictions; post-hoc recovery. Error bars show uncertainty, not additional runs.`;table(byId('math-table'),['Condition','Correct / tasks','Exact accuracy','95% Wilson interval'],rows.map(r=>[r.label,`${r.count} / ${r.n}`,(100*r.value).toFixed(2)+'%',r.interval.map(x=>(100*x).toFixed(2)+'%').join(' – ')]));}
 function physics(){if(!data)return;const family=byId('physics-family').value,horizon=byId('physics-horizon').value,metric=byId('physics-metric').value,methods=[['structured','Structured'],['matched','Matched neural'],['v3_1_frozen','Frozen V3.1'],['analytical_contacts','Analytical contacts']];const rows=methods.map(([key,label])=>{const cell=data.physics[family][`ood/${horizon}/${key}`];return{label,value:cell.means[metric],n:cell.n};});bars(byId('physics-chart'),rows,metric==='mse'?Math.max(...rows.map(r=>r.value))*1.08:1,metric!=='mse');byId('physics-note').textContent=`${family==='motion'?'Motion':'Interaction'} · ${horizon} steps · ${rows[0].n} independent OOD scenes. ${metric==='mse'?'Lower MSE is better.':metric==='success'?'Higher executed planning success is better.':'Nominal interval coverage is 95%; coverage alone does not establish useful calibration.'} Original superiority decision: NO_GO.`;table(byId('physics-table'),['Method',metric,'Independent scenes'],rows.map(r=>[r.label,r.value.toPrecision(10),r.n]));}
 function timeline(){const list=byId('release-timeline');list.replaceChildren();for(const r of data.timeline){const li=element('li'),copy=element('div');copy.append(element('h3',r.title),element('span',r.status,'label neutral'),element('p',r.text));if(r.source){const link=element('a','Inspect this version ↗');link.href=r.source;copy.append(link);}li.append(element('span',r.version,'timeline-version'),copy);list.append(li);}}
 document.querySelectorAll('[data-model]').forEach(button=>button.addEventListener('click',()=>{if(!data)return;const m=data.models.find(m=>m.id===button.dataset.model);document.querySelectorAll('[data-model]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));byId('model-title').textContent=m.name;byId('model-layers').replaceChildren(...m.layers.map(s=>element('p',s)));byId('model-parameters').textContent=m.parameters.toLocaleString('en-US')+' parameters';byId('model-description').textContent=m.description;}));
 const tabs=[...document.querySelectorAll('[data-field]')];tabs.forEach((button,i)=>{button.addEventListener('click',()=>tab(button.dataset.field));button.addEventListener('keydown',e=>{let next;if(e.key==='ArrowRight')next=(i+1)%tabs.length;if(e.key==='ArrowLeft')next=(i+tabs.length-1)%tabs.length;if(e.key==='Home')next=0;if(e.key==='End')next=tabs.length-1;if(next!==undefined){e.preventDefault();tab(tabs[next].dataset.field,true);}});});
 byId('trace-select').addEventListener('change',()=>{traceIndex=Number(byId('trace-select').value);byId('step-slider').value=0;renderTrace();});byId('step-slider').addEventListener('input',renderTrace);for(const [id,delta] of [['step-prev',-1],['step-next',1]])byId(id).addEventListener('click',()=>{byId('step-slider').value=Number(byId('step-slider').value)+delta;renderTrace();});
 ['math-seed','math-family'].forEach(id=>byId(id).addEventListener('change',math));['physics-family','physics-horizon','physics-metric'].forEach(id=>byId(id).addEventListener('change',physics));
 fetch(document.body.dataset.release).then(r=>{if(!r.ok)throw Error('Evidence unavailable');return r.json();}).then(value=>{if(value.schema!=='mindscape.announcement/1'||value.status!==document.body.dataset.status||value.scientific_updates!==0||value.neural_ood_predictions!==0||!Array.isArray(value.traces)||value.traces.length===0)throw Error('Incompatible release bundle');data=value;renderTrace();math();physics();timeline();byId('data-status').textContent=`Evidence snapshot: ${data.as_of}. Research source ${data.evidence_commit.slice(0,8)}. Versioned data; no model execution.`;}).catch(()=>{byId('data-status').textContent='Interactive evidence could not load. The original source files remain available in every section.';byId('trace-json').textContent='Recording unavailable. Open the linked original JSON.';});
})();

// Keep the hero navigation dark, then return to the site's light glass treatment.
(() => {
 const syncNavigation = () => document.body.classList.toggle('nav-scrolled', window.scrollY > 64);
 window.addEventListener('scroll', syncNavigation, {passive:true});
 window.addEventListener('pageshow', syncNavigation);
 syncNavigation();
})();
